public class Waechter {
    private String name;
    private int ruestung;

    public Waechter(String name, int ruestung) {
        this.name = name;
        this.ruestung = ruestung;
    }

    public String getName() { return name; }
    public void verstaerken(int punkte) {
        ruestung = ruestung + punkte;
    }
    public int abwehr() {
        return ruestung;
    }
}

