public class Hauptmann extends Waechter {
    private int schild;

    public Hauptmann(String name, int ruestung, int schild) {
        super(name, ruestung);
        this.schild = schild;
    }

    @Override
    public int abwehr() {
        return super.abwehr() + schild;
    }
